# owner: platform
"""Absence notices that go home to parents."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


# ---
def check_marks_belong(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks recorded for another student."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError("mark is for another student")


# ---
def render_notice(
    student: Student, missed: List[date]
) -> str:
    noun = "day" if len(missed) == 1 else "days"
    listed = ", ".join(item.isoformat() for item in missed)
    name = f"{student.first_name} {student.last_name}"
    text = f"{name} was absent on {len(missed)} {noun}"
    return f"Dear parent/guardian,\n\n{text}: {listed}.\n"


# ---
def build_absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    check_marks_belong(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to write about")
    return render_notice(student, missed)
